<?php
$suiteModule='activities';require __DIR__.'/../common.php';if (!isset($suiteWorkspace)) return;
$view=($_GET['view']??'list')==='calendar'?'calendar':'list';$selected=null;
if (!empty($_GET['id'])) {try {$selected=$suiteWorkspace->activity((int)$_GET['id']);}catch(RuntimeException $error){http_response_code(404);echo '<p class="alert alert-warning">'.$suiteEscape($error->getMessage()).'</p>';}}
$editing=$selected||isset($_GET['new']);
?>
<div class="suite-heading mb-3"><h4 class="m-0">Activities</h4><div class="suite-actions"><a class="btn btn-sm btn-outline-secondary" title="List view" aria-label="List view" href="<?php echo $suiteEscape($suiteUrl) ?>"><i class="fas fa-list"></i></a><a class="btn btn-sm btn-outline-secondary" title="Calendar view" aria-label="Calendar view" href="<?php echo $suiteEscape($suiteUrl) ?>&view=calendar"><i class="fas fa-calendar-alt"></i></a><a class="btn btn-sm btn-primary" href="<?php echo $suiteEscape($suiteUrl) ?>&new=1"><i class="fas fa-plus mr-1"></i> New Activity</a></div></div>
<?php if ($editing): ?>
<form class="suite-form" data-action="save_activity" data-redirect="<?php echo $suiteEscape($suiteUrl) ?>"><input type="hidden" name="id" value="<?php echo $selected['id']??'' ?>"><input type="hidden" name="version" value="<?php echo $selected['version']??'' ?>"><input type="hidden" name="request_key" value="<?php echo $selected['request_key']??bin2hex(random_bytes(20)) ?>">
<div class="row"><div class="form-group col-md-8"><label for="activity-title">Title</label><input class="form-control form-control-sm" id="activity-title" name="title" maxlength="200" value="<?php echo $suiteEscape($selected['title']??'') ?>" required></div><div class="form-group col-md-4"><label for="activity-kind">Type</label><select class="form-control form-control-sm" id="activity-kind" name="kind"><?php echo $suiteSelect([['id'=>'task','name'=>'Task'],['id'=>'event','name'=>'Event'],['id'=>'call','name'=>'Call']],'id','name',$selected['kind']??'task') ?></select></div></div>
<div class="row"><?php foreach (['starts_at'=>'Start / Due','ends_at'=>'End'] as $field=>$label): ?><div class="form-group col-md-3"><label for="activity-<?php echo $field ?>"><?php echo $label ?></label><input class="form-control form-control-sm" id="activity-<?php echo $field ?>" name="<?php echo $field ?>" type="datetime-local" value="<?php echo $suiteEscape(isset($selected[$field])?str_replace(' ','T',substr($selected[$field],0,16)):($field==='starts_at'?date('Y-m-d\TH:i'):'')) ?>" <?php echo $field==='starts_at'?'required':'' ?>></div><?php endforeach ?><div class="form-group col-md-3"><label for="activity-status">Status</label><select class="form-control form-control-sm" id="activity-status" name="status"><?php foreach (['open','in_progress','completed','cancelled'] as $status): ?><option value="<?php echo $status ?>" <?php echo ($selected['status']??'open')===$status?'selected':'' ?>><?php echo ucwords(str_replace('_',' ',$status)) ?></option><?php endforeach ?></select></div><div class="form-group col-md-3"><label for="activity-priority">Priority</label><select class="form-control form-control-sm" id="activity-priority" name="priority"><?php foreach (['low','normal','high'] as $priority): ?><option value="<?php echo $priority ?>" <?php echo ($selected['priority']??'normal')===$priority?'selected':'' ?>><?php echo ucfirst($priority) ?></option><?php endforeach ?></select></div></div>
<div class="row"><div class="form-group col-md-6"><label for="activity-assignee">Assigned To</label><select class="form-control form-control-sm" id="activity-assignee" name="assigned_to"><option value="">Unassigned</option><?php echo $suiteSelect($suiteOptions['users'],'id','username',$selected['assigned_to']??$suiteUser) ?></select></div><div class="form-group col-md-6"><label for="activity-party">Related Party</label><select class="form-control form-control-sm suite-search-select" id="activity-party" name="party_id"><option value="">None</option><?php echo $suiteSelect($suiteOptions['parties'],'id','display_name',$selected['party_id']??null) ?></select></div></div><div class="form-group"><label for="activity-notes">Notes</label><textarea class="form-control form-control-sm" id="activity-notes" name="notes" maxlength="10000" rows="5"><?php echo $suiteEscape($selected['notes']??'') ?></textarea></div><button class="btn btn-sm btn-primary" type="submit"><i class="fas fa-save mr-1"></i> Save Activity</button></form>
<?php elseif ($view==='calendar'): ?>
<link rel="stylesheet" href="<?php echo base_url ?>plugins/fullcalendar/main.min.css"><script src="<?php echo base_url ?>plugins/fullcalendar/main.min.js"></script><div id="suite-calendar"></div>
<?php else: ?>
<div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><th>Activity</th><th>Type</th><th>Start / Due</th><th>Status</th><th>Priority</th><th>Assigned To</th><th>Party</th></tr></thead><tbody><?php foreach ($suiteWorkspace->activities() as $row): ?><tr><td><a href="<?php echo $suiteEscape($suiteUrl) ?>&id=<?php echo $row['id'] ?>"><?php echo $suiteEscape($row['title']) ?></a></td><td><?php echo ucfirst($row['kind']) ?></td><td class="text-nowrap <?php echo $row['starts_at']<date('Y-m-d H:i:s')&&!in_array($row['status'],['completed','cancelled'])?'text-danger':'' ?>"><?php echo $row['starts_at'] ?></td><td><?php echo ucwords(str_replace('_',' ',$row['status'])) ?></td><td><?php echo ucfirst($row['priority']) ?></td><td><?php echo $suiteEscape($row['assignee']??'Unassigned') ?></td><td><?php echo $suiteEscape($row['party_name']??'') ?></td></tr><?php endforeach ?></tbody></table></div>
<?php endif ?>
</div>
